// On-device ("local") brain chat — web build.
//
// Renders a model picker and a self-contained chat whose replies are
// generated by the standalone engine page (/local-brain/index.html,
// a hidden iframe running WebLLM on the device GPU). Nothing here goes
// to the server: local chats are not saved, have no tools, and every
// assistant bubble is labeled as coming from the small local model so
// it is never mistaken for the full cloud Arthur.

import { useEffect, useReducer, useRef, useState } from "react";
import { Pressable, ScrollView, Text, TextInput, View } from "react-native";
import { type EngineEvent, type EngineRequest, isEngineEvent } from "../ondevice/protocol";
import {
  canChatLocally,
  canDeleteModelCache,
  detectLocalBrainSupport,
  downloadWarning,
  formatBytes,
  initialLocalBrainState,
  LOCAL_MODELS,
  LOCAL_REPLY_LABEL,
  localBrainReducer,
  resolveSavedModelId,
} from "./brain";
import { Button, Card, Chip, colors, ErrorNotice, s } from "./ui";

interface LocalMessage {
  id: string;
  role: "user" | "assistant";
  text: string;
}

const MODEL_STORAGE_KEY = "openmuse.localBrainModel";
const ENGINE_LOAD_TIMEOUT_MS = 15_000;

function deviceHasWebGPU(): boolean {
  if (typeof navigator === "undefined") return false;
  const gpu = (navigator as unknown as { gpu?: unknown }).gpu;
  return typeof gpu === "object" && gpu !== null;
}

function savedModelId(): string {
  try {
    return resolveSavedModelId(window.localStorage.getItem(MODEL_STORAGE_KEY));
  } catch {
    // Private mode / storage disabled: fall back to the default model.
    return resolveSavedModelId(null);
  }
}

export function LocalBrainChat() {
  const [support] = useState(() =>
    detectLocalBrainSupport({ isWeb: true, hasWebGPU: deviceHasWebGPU() }),
  );
  const [state, dispatch] = useReducer(localBrainReducer, initialLocalBrainState);
  const [modelId, setModelId] = useState(savedModelId);
  const [messages, setMessages] = useState<LocalMessage[]>([]);
  const [draft, setDraft] = useState("");
  const [enginePageLoaded, setEnginePageLoaded] = useState(false);
  const [genError, setGenError] = useState("");
  /** Model ids with weights cached on this device; null until the engine reports. */
  const [cachedModelIds, setCachedModelIds] = useState<string[] | null>(null);
  const [deletingModelId, setDeletingModelId] = useState<string | null>(null);
  const frame = useRef<HTMLIFrameElement | null>(null);
  const generation = useRef<string | null>(null);
  const list = useRef<ScrollView>(null);
  // Follow the newest message only while the user is already at the end
  // of the list (the cloud chat's pattern). Without this guard every
  // content-size change — each streamed token grows the reply — yanked
  // the list back to the bottom and the user could not scroll up to
  // read earlier messages.
  const followLatest = useRef(true);
  const stateRef = useRef(state);
  stateRef.current = state;

  const post = (request: EngineRequest) => {
    frame.current?.contentWindow?.postMessage(request, window.location.origin);
  };

  useEffect(() => {
    if (!support.supported) return;
    const onMessage = (event: MessageEvent<unknown>) => {
      if (event.origin !== window.location.origin) return;
      if (event.source !== frame.current?.contentWindow) return;
      if (!isEngineEvent(event.data)) return;
      const engineEvent: EngineEvent = event.data;
      switch (engineEvent.kind) {
        case "local-brain:hello":
          setEnginePageLoaded(true);
          frame.current?.contentWindow?.postMessage(
            { kind: "local-brain:cache-status" } satisfies EngineRequest,
            window.location.origin,
          );
          break;
        case "local-brain:cache":
          setCachedModelIds(engineEvent.cached);
          break;
        case "local-brain:cache-deleted":
          setDeletingModelId(null);
          break;
        case "local-brain:progress":
          dispatch({ type: "progress", progress: engineEvent.progress, text: engineEvent.text });
          break;
        case "local-brain:ready":
          dispatch({ type: "engine-ready" });
          break;
        case "local-brain:delta":
          if (engineEvent.id === generation.current)
            setMessages((current) =>
              current.map((message) =>
                message.id === engineEvent.id ? { ...message, text: engineEvent.text } : message,
              ),
            );
          break;
        case "local-brain:done":
          if (engineEvent.id === generation.current) {
            generation.current = null;
            dispatch({ type: "generation-finished" });
          }
          break;
        case "local-brain:error":
          setDeletingModelId(null);
          if (engineEvent.id && engineEvent.id === generation.current) {
            generation.current = null;
            setGenError(engineEvent.message);
            dispatch({ type: "generation-finished" });
          } else if (stateRef.current.stage === "downloading") {
            dispatch({ type: "failed", message: engineEvent.message });
          } else {
            setGenError(engineEvent.message);
          }
          break;
      }
    };
    window.addEventListener("message", onMessage);
    return () => window.removeEventListener("message", onMessage);
  }, [support.supported]);

  // If the engine page never announces itself, its files are missing
  // (e.g. a dev server without the engine bundle) — say so plainly
  // instead of leaving the download button spinning forever.
  useEffect(() => {
    if (!support.supported || enginePageLoaded) return;
    const timer = window.setTimeout(() => {
      if (stateRef.current.stage === "downloading")
        dispatch({
          type: "failed",
          message:
            "The on-device engine didn't load, so the local model can't start here. Cloud chat still works.",
        });
    }, ENGINE_LOAD_TIMEOUT_MS);
    return () => window.clearTimeout(timer);
  }, [support.supported, enginePageLoaded]);

  function startModel(id: string) {
    setModelId(id);
    setGenError("");
    try {
      window.localStorage.setItem(MODEL_STORAGE_KEY, id);
    } catch {
      // Selection persistence is a nicety, not a requirement.
    }
    dispatch({ type: "init-started", modelId: id });
    post({ kind: "local-brain:init", modelId: id });
  }

  function removeDownload(id: string) {
    setDeletingModelId(id);
    setGenError("");
    post({ kind: "local-brain:delete-cache", modelId: id });
  }

  function send() {
    const text = draft.trim();
    if (!text || !canChatLocally(state) || generation.current) return;
    followLatest.current = true;
    const userMessage: LocalMessage = {
      id: `local-user-${Date.now()}`,
      role: "user",
      text,
    };
    const replyId = `local-reply-${Date.now()}`;
    const history = [...messages, userMessage];
    setMessages([...history, { id: replyId, role: "assistant", text: "" }]);
    setDraft("");
    setGenError("");
    generation.current = replyId;
    dispatch({ type: "generation-started" });
    post({
      kind: "local-brain:generate",
      id: replyId,
      messages: history.map((message) => ({ role: message.role, content: message.text })),
    });
  }

  function stop() {
    if (generation.current) post({ kind: "local-brain:interrupt", id: generation.current });
  }

  if (!support.supported)
    return (
      <Card style={{ padding: 16, gap: 8 }}>
        <Text style={s.heading}>On-device brain unavailable</Text>
        <Text style={s.muted}>{support.reason}</Text>
      </Card>
    );

  const generating = state.stage === "generating";
  const downloading = state.stage === "downloading";

  return (
    <View style={{ flex: 1, gap: 12 }}>
      {/* The engine page: invisible, lazily loaded only in local mode. */}
      <iframe
        ref={frame}
        title="On-device model engine"
        src="/local-brain/index.html"
        style={{ width: 1, height: 1, border: 0, opacity: 0, position: "absolute" }}
      />
      <Card style={{ padding: 16, gap: 10 }}>
        <Text style={s.heading}>Pick a model for this phone</Text>
        <Text style={s.muted}>
          The model downloads once, then runs entirely on this device — no API key, no server, works
          offline. It is a small model: chat only, no tools, no access to your apps or files, and
          simpler answers than the cloud brain.
        </Text>
        {LOCAL_MODELS.map((model) => {
          const isLoaded =
            state.stage !== "idle" && state.modelId === model.id && state.stage !== "error";
          const isDownloadingThis = downloading && state.modelId === model.id;
          const isCached = cachedModelIds?.includes(model.id) ?? false;
          const canDelete = canDeleteModelCache(model.id, state, cachedModelIds ?? []);
          const isDeletingThis = deletingModelId === model.id;
          return (
            <View key={model.id} style={{ gap: 6, paddingTop: 6 }}>
              <View style={[s.row, { gap: 8, flexWrap: "wrap" }]}>
                <Text style={[s.text, { fontWeight: "600" }]}>{model.label}</Text>
                <Chip>{`About ${formatBytes(model.downloadBytes)} download`}</Chip>
                {isLoaded && !isDownloadingThis && <Chip tint={colors.sky}>Loaded</Chip>}
                {isCached && !isLoaded && <Chip>Downloaded ✓</Chip>}
              </View>
              <Text style={s.muted}>{model.blurb}</Text>
              {!isCached && <Text style={s.small}>{downloadWarning(model)}</Text>}
              {isDownloadingThis ? (
                <View style={{ gap: 6 }}>
                  <View
                    style={{
                      height: 8,
                      borderRadius: 4,
                      backgroundColor: "#EEEEF0",
                      overflow: "hidden",
                    }}
                  >
                    <View
                      style={{
                        height: 8,
                        width: `${Math.round(state.progress * 100)}%`,
                        backgroundColor: colors.blue,
                      }}
                    />
                  </View>
                  <Text style={s.small}>
                    {`Downloading… ${Math.round(state.progress * 100)}%`}
                    {state.note ? ` — ${state.note}` : ""}
                  </Text>
                </View>
              ) : (
                <View style={[s.row, { gap: 8, flexWrap: "wrap" }]}>
                  <Button
                    small
                    disabled={downloading || (isLoaded && state.modelId === model.id)}
                    onPress={() => startModel(model.id)}
                    style={{ alignSelf: "flex-start" }}
                  >
                    {isLoaded
                      ? "Using this model"
                      : isCached
                        ? "Use this model"
                        : "Download & use this model"}
                  </Button>
                  {canDelete && (
                    <Button
                      small
                      disabled={deletingModelId !== null || downloading}
                      onPress={() => removeDownload(model.id)}
                      style={{ alignSelf: "flex-start" }}
                    >
                      {isDeletingThis
                        ? "Removing…"
                        : `Remove download (free ${formatBytes(model.downloadBytes)})`}
                    </Button>
                  )}
                </View>
              )}
              {isCached && isLoaded && !isDownloadingThis && (
                <Text style={s.small}>
                  To free its space, switch to another model first — then its Remove button appears
                  here.
                </Text>
              )}
            </View>
          );
        })}
        {state.stage === "error" && (
          <>
            <ErrorNotice error={state.note} />
            <Button small onPress={() => startModel(modelId)} style={{ alignSelf: "flex-start" }}>
              Try loading again
            </Button>
          </>
        )}
      </Card>

      <ScrollView
        ref={list}
        style={{ flex: 1 }}
        showsVerticalScrollIndicator={false}
        contentContainerStyle={{ gap: 13, paddingBottom: 16, flexGrow: 1 }}
        onScroll={({ nativeEvent: { contentOffset, contentSize, layoutMeasurement } }) => {
          followLatest.current =
            contentSize.height - contentOffset.y - layoutMeasurement.height < 100;
        }}
        scrollEventThrottle={100}
        onContentSizeChange={() => {
          if (followLatest.current) list.current?.scrollToEnd({ animated: false });
        }}
        keyboardShouldPersistTaps="handled"
      >
        {!messages.length ? (
          <Text style={[s.muted, { textAlign: "center", paddingVertical: 20, lineHeight: 22 }]}>
            {state.stage === "ready"
              ? "The local model is ready. Say hello — replies are generated on this phone."
              : "Load a model above, then chat here. On-device chats stay on this phone and aren't saved."}
          </Text>
        ) : (
          messages.map((message) => {
            const user = message.role === "user";
            return (
              <View
                key={message.id}
                style={{ alignSelf: user ? "flex-end" : "flex-start", maxWidth: "92%", gap: 4 }}
              >
                {!user && <Text style={s.small}>{LOCAL_REPLY_LABEL}</Text>}
                <View
                  style={{
                    paddingHorizontal: 16,
                    paddingVertical: 13,
                    borderRadius: 22,
                    borderBottomRightRadius: user ? 7 : 22,
                    borderBottomLeftRadius: user ? 22 : 7,
                    backgroundColor: user ? colors.blue : "#EEEEF0",
                  }}
                >
                  <Text selectable style={[s.text, { fontSize: 16, lineHeight: 24 }]}>
                    {message.text || (generating ? "Thinking…" : "")}
                  </Text>
                </View>
              </View>
            );
          })
        )}
        <ErrorNotice error={genError} />
      </ScrollView>

      <View
        style={{
          backgroundColor: "#FFF",
          borderRadius: 32,
          borderWidth: 1,
          borderColor: "#EEF0F2",
          padding: 8,
          flexDirection: "row",
          gap: 7,
          alignItems: "flex-end",
        }}
      >
        <TextInput
          accessibilityLabel="Message the on-device model"
          value={draft}
          onChangeText={setDraft}
          placeholder={
            state.stage === "ready"
              ? "Message (answered on this phone)…"
              : state.stage === "downloading"
                ? "Model loading…"
                : "Load a model above first"
          }
          placeholderTextColor="#949B9F"
          selectionColor={colors.blueDark}
          style={{
            flex: 1,
            color: colors.text,
            minHeight: 44,
            maxHeight: 140,
            fontSize: 17,
            lineHeight: 24,
            paddingHorizontal: 10,
            paddingTop: 10,
            paddingBottom: 10,
          }}
          multiline
          editable={state.stage === "ready" || generating}
          onKeyPress={(event) => {
            if (
              event.nativeEvent.key === "Enter" &&
              !("shiftKey" in event.nativeEvent && event.nativeEvent.shiftKey)
            ) {
              event.preventDefault();
              send();
            }
          }}
        />
        <Pressable
          accessibilityRole="button"
          accessibilityLabel={generating ? "Stop reply" : "Send message"}
          disabled={!generating && (!draft.trim() || !canChatLocally(state))}
          onPress={generating ? stop : send}
          style={({ pressed }) => ({
            width: 44,
            height: 44,
            borderRadius: 24,
            backgroundColor: generating || draft.trim() ? colors.blue : "#F3F5F6",
            alignItems: "center",
            justifyContent: "center",
            transform: [{ scale: pressed ? 0.94 : 1 }],
          })}
        >
          <Text style={{ fontSize: 18, color: colors.text }}>{generating ? "■" : "↑"}</Text>
        </Pressable>
      </View>
    </View>
  );
}
